import java.math.BigDecimal
import java.math.RoundingMode

class Ledger {
    private val balances = HashMap<String, BigDecimal>()
    private val log = HashMap<String, MutableList<BigDecimal>>()

    fun openAccount(id: String, initial: BigDecimal = BigDecimal.ZERO) {
        if (balances.containsKey(id)) {
            throw IllegalArgumentException("account already exists: $id")
        }
        val normalized = normalize(initial)
        require(normalized >= BigDecimal.ZERO) { "initial amount must not be negative" }
        balances[id] = normalized
        log[id] = mutableListOf()
    }

    fun balance(id: String): BigDecimal =
        balances[id] ?: throw NoSuchElementException("no such account: $id")

    fun transfer(from: String, to: String, amount: BigDecimal) {
        val a = normalize(amount)
        require(a > BigDecimal.ZERO) { "amount must be positive" }

        // Resolve both accounts up front so an unknown id fails before any mutation.
        val fromBalance = balances[from] ?: throw NoSuchElementException("no such account: $from")
        val toBalance = balances[to] ?: throw NoSuchElementException("no such account: $to")

        if (fromBalance - a < BigDecimal.ZERO) {
            throw IllegalStateException("insufficient funds")
        }

        balances[from] = fromBalance - a
        balances[to] = toBalance + a
        log.getValue(from).add(a.negate())
        log.getValue(to).add(a)
    }

    fun history(id: String): List<BigDecimal> {
        val entries = log[id] ?: throw NoSuchElementException("no such account: $id")
        return entries.toList()
    }

    private fun normalize(amount: BigDecimal): BigDecimal {
        if (amount.scale() > 2 && amount.stripTrailingZeros().scale() > 2) {
            throw IllegalArgumentException("amount has more than 2 decimal places: $amount")
        }
        return amount.setScale(2, RoundingMode.UNNECESSARY)
    }

    companion object {
        fun split(total: BigDecimal, n: Int): List<BigDecimal> {
            require(n > 0) { "n must be positive" }
            val normalized = normalize(total)
            require(normalized > BigDecimal.ZERO) { "total must be positive" }

            val cents = normalized.movePointRight(2).toBigIntegerExact()
            val base = cents.divide(java.math.BigInteger.valueOf(n.toLong()))
            val remainder = cents.mod(java.math.BigInteger.valueOf(n.toLong())).toInt()

            return List(n) { index ->
                val extra = if (index < remainder) java.math.BigInteger.ONE else java.math.BigInteger.ZERO
                BigDecimal(base.add(extra)).movePointLeft(2).setScale(2, RoundingMode.UNNECESSARY)
            }
        }
    }
}
