class LruCache<K, V>(val capacity: Int, private val onEvict: (K, V) -> Unit = { _, _ -> }) {
    init {
        require(capacity >= 1) { "capacity must be >= 1" }
    }

    private val map = LinkedHashMap<K, V>()

    operator fun get(key: K): V? {
        val value = map.remove(key)
        if (value != null) {
            map[key] = value
            return value
        }
        if (map.containsKey(key)) {
            map[key] = value as V
            return value
        }
        return null
    }

    operator fun set(key: K, value: V) {
        if (map.containsKey(key)) {
            map.remove(key)
            map[key] = value
            return
        }
        map[key] = value
        if (map.size > capacity) {
            val eldest = map.entries.iterator()
            val evicted = eldest.next()
            eldest.remove()
            onEvict(evicted.key, evicted.value)
        }
    }

    fun remove(key: K): V? = map.remove(key)

    val size: Int
        get() = map.size

    fun keys(): List<K> = map.keys.toList()

    operator fun contains(key: K): Boolean = map.containsKey(key)
}
