```kotlin
fun toJson(value: Any?, indent: Int = 0): String {
    val sb = StringBuilder()
    writeValue(sb, value, indent, 0)
    return sb.toString()
}

private fun writeValue(sb: StringBuilder, value: Any?, indent: Int, level: Int) {
    when (value) {
        null -> sb.append("null")
        is Boolean -> sb.append(value.toString())
        is String -> writeString(sb, value)
        is Int -> sb.append(value.toString())
        is Long -> sb.append(value.toString())
        is Double -> {
            if (!value.isFinite()) throw IllegalArgumentException("Non-finite double: $value")
            sb.append(value.toString())
        }
        is Float -> {
            if (!value.isFinite()) throw IllegalArgumentException("Non-finite float: $value")
            sb.append(value.toString())
        }
        is Enum<*> -> writeString(sb, value.name)
        is Map<*, *> -> writeMap(sb, value, indent, level)
        is List<*> -> writeList(sb, value, indent, level)
        is Array<*> -> writeList(sb, value.asList(), indent, level)
        else -> throw IllegalArgumentException("Unsupported type: ${value::class}")
    }
}

private fun writeMap(sb: StringBuilder, map: Map<*, *>, indent: Int, level: Int) {
    if (map.isEmpty()) {
        sb.append("{}")
        return
    }
    sb.append('{')
    val pretty = indent > 0
    var first = true
    for ((k, v) in map) {
        if (k !is String) throw IllegalArgumentException("Non-String map key: $k")
        if (pretty) {
            if (!first) sb.append(',')
            sb.append('\n')
            appendIndent(sb, indent, level + 1)
        } else {
            if (!first) sb.append(',')
        }
        first = false
        writeString(sb, k)
        sb.append(':')
        if (pretty) sb.append(' ')
        writeValue(sb, v, indent, level + 1)
    }
    if (pretty) {
        sb.append('\n')
        appendIndent(sb, indent, level)
    }
    sb.append('}')
}

private fun writeList(sb: StringBuilder, list: List<*>, indent: Int, level: Int) {
    if (list.isEmpty()) {
        sb.append("[]")
        return
    }
    sb.append('[')
    val pretty = indent > 0
    var first = true
    for (v in list) {
        if (pretty) {
            if (!first) sb.append(',')
            sb.append('\n')
            appendIndent(sb, indent, level + 1)
        } else {
            if (!first) sb.append(',')
        }
        first = false
        writeValue(sb, v, indent, level + 1)
    }
    if (pretty) {
        sb.append('\n')
        appendIndent(sb, indent, level)
    }
    sb.append(']')
}

private fun appendIndent(sb: StringBuilder, indent: Int, level: Int) {
    repeat(indent * level) { sb.append(' ') }
}

private fun writeString(sb: StringBuilder, s: String) {
    sb.append('"')
    for (c in s) {
        when (c) {
            '"' -> sb.append("\\\"")
            '\\' -> sb.append("\\\\")
            '\b' -> sb.append("\\b")
            '\u000C' -> sb.append("\\f")
            '\n' -> sb.append("\\n")
            '\r' -> sb.append("\\r")
            '\t' -> sb.append("\\t")
            else -> {
                if (c.code < 0x20) {
                    sb.append("\\u00")
                    sb.append(HEX[c.code shr 4])
                    sb.append(HEX[c.code and 0xF])
                } else {
                    sb.append(c)
                }
            }
        }
    }
    sb.append('"')
}

private val HEX = "0123456789abcdef".toCharArray()
