sealed class Token {
    abstract val pos: Int  // 0-based index of the token's first character
    data class Ident(val name: String, override val pos: Int) : Token()
    data class Str(val value: String, override val pos: Int) : Token()
    data class Num(val value: Double, override val pos: Int) : Token()
    data class Op(val symbol: String, override val pos: Int) : Token()
    data class Paren(val open: Boolean, override val pos: Int) : Token()
}
class TokenizeException(message: String, val pos: Int) : Exception(message)
fun tokenize(input: String): List<Token>

private fun isIdentStart(c: Char): Boolean = c in 'A'..'Z' || c in 'a'..'z' || c == '_'
private fun isIdentPart(c: Char): Boolean = isIdentStart(c) || c in '0'..'9' || c == '.'
private fun isDigit(c: Char): Boolean = c in '0'..'9'
private fun isWhitespace(c: Char): Boolean = c == ' ' || c == '\t' || c == '\n'

private fun allowsLeadingMinus(prev: Token?): Boolean =
    prev == null || prev is Token.Op || (prev is Token.Paren && prev.open)

fun tokenize(input: String): List<Token> {
    val tokens = mutableListOf<Token>()
    var i = 0
    val n = input.length

    while (i < n) {
        val c = input[i]
        when {
            isWhitespace(c) -> {
                i++
            }
            isIdentStart(c) -> {
                val start = i
                i++
                while (i < n && isIdentPart(input[i])) i++
                tokens.add(Token.Ident(input.substring(start, i), start))
            }
            isDigit(c) || (c == '-' && allowsLeadingMinus(tokens.lastOrNull()) && i + 1 < n && isDigit(input[i + 1])) -> {
                val start = i
                if (c == '-') i++
                while (i < n && isDigit(input[i])) i++
                if (i < n && input[i] == '.') {
                    i++
                    if (i >= n || !isDigit(input[i])) {
                        throw TokenizeException("Malformed number", start)
                    }
                    while (i < n && isDigit(input[i])) i++
                }
                if (i < n && isIdentStart(input[i])) {
                    throw TokenizeException("Malformed number", start)
                }
                tokens.add(Token.Num(input.substring(start, i).toDouble(), start))
            }
            c == '"' || c == '\'' -> {
                val start = i
                val quote = c
                i++
                val sb = StringBuilder()
                var closed = false
                while (i < n) {
                    val ch = input[i]
                    if (ch == '\\') {
                        if (i + 1 >= n) {
                            throw TokenizeException("Unterminated string", start)
                        }
                        val esc = input[i + 1]
                        sb.append(if (esc == 'n') '\n' else esc)
                        i += 2
                    } else if (ch == quote) {
                        i++
                        closed = true
                        break
                    } else {
                        sb.append(ch)
                        i++
                    }
                }
                if (!closed) {
                    throw TokenizeException("Unterminated string", start)
                }
                tokens.add(Token.Str(sb.toString(), start))
            }
            c == '(' || c == ')' -> {
                tokens.add(Token.Paren(c == '(', i))
                i++
            }
            c == '=' || c == '!' || c == '<' || c == '>' -> {
                val two = if (i + 1 < n) input.substring(i, i + 2) else ""
                when (two) {
                    "==", "!=", "<=", ">=" -> {
                        tokens.add(Token.Op(two, i))
                        i += 2
                    }
                    else -> {
                        when (c) {
                            '<', '>' -> {
                                tokens.add(Token.Op(c.toString(), i))
                                i++
                            }
                            '!' -> {
                                tokens.add(Token.Op("!", i))
                                i++
                            }
                            else -> throw TokenizeException("Unexpected character '$c'", i)
                        }
                    }
                }
            }
            c == '&' || c == '|' -> {
                if (i + 1 < n && input[i + 1] == c) {
                    tokens.add(Token.Op("$c$c", i))
                    i += 2
                } else {
                    throw TokenizeException("Unexpected character '$c'", i)
                }
            }
            else -> {
                throw TokenizeException("Unexpected character '$c'", i)
            }
        }
    }

    return tokens
}
