import re


def _split_lines_keepends(text):
    """Split text into lines, keeping newline characters."""
    if text == "":
        return []
    lines = []
    start = 0
    n = len(text)
    i = 0
    while i < n:
        if text[i] == "\n":
            lines.append(text[start:i + 1])
            i += 1
            start = i
        else:
            i += 1
    if start < n:
        lines.append(text[start:])
    return lines


_HUNK_RE = re.compile(r"^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@(.*)$")


def apply_patch(original: str, diff: str) -> str:
    orig_lines = _split_lines_keepends(original)

    diff_lines = diff.split("\n")
    if diff_lines and diff_lines[-1] == "":
        diff_lines.pop()

    idx = 0
    while idx < len(diff_lines) and not diff_lines[idx].startswith("@@"):
        idx += 1

    hunks = []
    while idx < len(diff_lines):
        line = diff_lines[idx]
        if not line.startswith("@@"):
            raise ValueError("Expected hunk header, got: %r" % line)
        m = _HUNK_RE.match(line)
        if not m:
            raise ValueError("Invalid hunk header: %r" % line)
        old_start = int(m.group(1))
        old_count = int(m.group(2)) if m.group(2) is not None else 1
        new_start = int(m.group(3))
        new_count = int(m.group(4)) if m.group(4) is not None else 1
        idx += 1

        body = []
        while idx < len(diff_lines):
            bl = diff_lines[idx]
            if bl.startswith("@@"):
                break
            if bl.startswith("\\"):
                if not body:
                    raise ValueError("No-newline marker without preceding line")
                kind, text, _ = body[-1]
                body[-1] = (kind, text, False)
                idx += 1
                continue
            if bl == "":
                raise ValueError("Empty line in hunk body")
            kind = bl[0]
            if kind not in (" ", "-", "+"):
                raise ValueError("Invalid hunk body line: %r" % bl)
            body.append((kind, bl[1:], True))
            idx += 1

        actual_old = sum(1 for k, _, _ in body if k in (" ", "-"))
        actual_new = sum(1 for k, _, _ in body if k in (" ", "+"))
        if actual_old != old_count:
            raise ValueError(
                "Old count mismatch: header %d, body %d" % (old_count, actual_old)
            )
        if actual_new != new_count:
            raise ValueError(
                "New count mismatch: header %d, body %d" % (new_count, actual_new)
            )

        hunks.append((old_start, old_count, body))

    result = list(orig_lines)
    offset = 0

    for old_start, old_count, body in hunks:
        if old_count == 0:
            if old_start == 0:
                pos = 0
            else:
                pos = old_start
            pos += offset
        else:
            pos = (old_start - 1) + offset

        cursor = pos
        new_segment = []
        for kind, text, has_nl in body:
            if kind == " ":
                if cursor >= len(result):
                    raise ValueError("Hunk context beyond end of file")
                expected = text + ("\n" if has_nl else "")
                if result[cursor] != expected:
                    raise ValueError(
                        "Context mismatch at line %d: expected %r, got %r"
                        % (cursor + 1, expected, result[cursor])
                    )
                new_segment.append(result[cursor])
                cursor += 1
            elif kind == "-":
                if cursor >= len(result):
                    raise ValueError("Hunk removal beyond end of file")
                expected = text + ("\n" if has_nl else "")
                if result[cursor] != expected:
                    raise ValueError(
                        "Removal mismatch at line %d: expected %r, got %r"
                        % (cursor + 1, expected, result[cursor])
                    )
                cursor += 1
            else:  # "+"
                new_segment.append(text + ("\n" if has_nl else ""))

        removed_count = old_count
        result[pos:pos + removed_count] = new_segment

        added_count = sum(1 for k, _, _ in body if k == "+")
        offset += added_count - removed_count

    return "".join(result)
