import asyncio


async def gather_limited(factories, limit: int, timeout: float | None = None) -> list:
    if limit < 1:
        raise ValueError("limit must be >= 1")

    n = len(factories)
    if n == 0:
        return []

    results = [None] * n
    running = {}  # asyncio.Task -> index

    it = iter(enumerate(factories))

    async def run_one(idx, factory):
        # Create the awaitable inside the task so the factory isn't called
        # before the task is about to start.
        awaitable = factory()
        if timeout is not None:
            return await asyncio.wait_for(awaitable, timeout)
        return await awaitable

    try:
        # Fill initial slots.
        while len(running) < limit:
            try:
                idx, factory = next(it)
            except StopIteration:
                break
            task = asyncio.ensure_future(run_one(idx, factory))
            running[task] = idx

        while running:
            done, _ = await asyncio.wait(
                running.keys(), return_when=asyncio.FIRST_COMPLETED
            )
            # Collect exceptions; pick the one that happened first in time.
            # asyncio doesn't expose completion timestamps, so we process
            # all done tasks and pick the first exception encountered among
            # them; since we can't know exact ordering, we approximate by
            # checking tasks in completion order returned by asyncio.wait
            # (done is a set, order undefined). To be safe, we track the
            # first exception and re-raise after cancelling.
            first_exc = None
            for task in done:
                idx = running.pop(task)
                if task.cancelled():
                    continue
                exc = task.exception()
                if exc is not None:
                    if first_exc is None:
                        first_exc = exc
                    continue
                results[idx] = task.result()

            if first_exc is not None:
                # Cancel all remaining running tasks and wait for cleanup.
                for t in list(running):
                    t.cancel()
                if running:
                    await asyncio.gather(*running.keys(), return_exceptions=True)
                raise first_exc

            # Start new tasks as slots free up.
            while len(running) < limit:
                try:
                    idx, factory = next(it)
                except StopIteration:
                    break
                task = asyncio.ensure_future(run_one(idx, factory))
                running[task] = idx

        return results

    except asyncio.CancelledError:
        for t in list(running):
            t.cancel()
        if running:
            await asyncio.gather(*running.keys(), return_exceptions=True)
        raise
    except BaseException:
        for t in list(running):
            t.cancel()
        if running:
            await asyncio.gather(*running.keys(), return_exceptions=True)
        raise
