import re

MONTH_NAMES = {
    'JAN': 1, 'FEB': 2, 'MAR': 3, 'APR': 4, 'MAY': 5, 'JUN': 6,
    'JUL': 7, 'AUG': 8, 'SEP': 9, 'OCT': 10, 'NOV': 11, 'DEC': 12,
}
DAY_NAMES = {
    'SUN': 0, 'MON': 1, 'TUE': 2, 'WED': 3, 'THU': 4, 'FRI': 5, 'SAT': 6,
}


def _parse_value(token, names, lo, hi, field):
    token = token.strip()
    if names is not None and token.upper() in names:
        return names[token.upper()]
    if not re.fullmatch(r'\d+', token):
        raise ValueError("invalid value %r in field %r" % (token, field))
    v = int(token)
    if v < lo or v > hi:
        raise ValueError("value %d out of range [%d,%d] in field %r" % (v, lo, hi, field))
    return v


def _parse_field(text, lo, hi, names, field):
    """Return a set of allowed values for a single cron field."""
    result = set()
    for item in text.split(','):
        item = item.strip()
        if item == '':
            raise ValueError("empty item in field %r" % field)

        step = 1
        base = item
        if '/' in item:
            parts = item.split('/')
            if len(parts) != 2:
                raise ValueError("invalid step in item %r of field %r" % (item, field))
            base, step_str = parts
            if not re.fullmatch(r'\d+', step_str):
                raise ValueError("invalid step %r in field %r" % (step_str, field))
            step = int(step_str)
            if step <= 0:
                raise ValueError("zero step in field %r" % field)

        if base == '*':
            start, end = lo, hi
            if '/' in item:
                start, end = lo, hi
        elif '-' in base:
            parts = base.split('-')
            if len(parts) != 2:
                raise ValueError("invalid range %r in field %r" % (base, field))
            start = _parse_value(parts[0], names, lo, hi, field)
            end = _parse_value(parts[1], names, lo, hi, field)
            if start > end:
                raise ValueError("range A > B in field %r" % field)
        else:
            start = _parse_value(base, names, lo, hi, field)
            if '/' in item:
                end = hi
            else:
                end = start

        for v in range(start, end + 1, step):
            result.add(v)
    return result


def next_fire(expr: str, after: datetime.datetime) -> datetime.datetime:
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("expected 5 fields, got %d" % len(fields))

    minutes = _parse_field(fields[0], 0, 59, None, 'minute')
    hours = _parse_field(fields[1], 0, 23, None, 'hour')
    doms = _parse_field(fields[2], 1, 31, None, 'day-of-month')
    months = _parse_field(fields[3], 1, 12, MONTH_NAMES, 'month')
    dows_raw = _parse_field(fields[4], 0, 7, DAY_NAMES, 'day-of-week')
    dows = set()
    for d in dows_raw:
        dows.add(0 if d == 7 else d)

    dom_restricted = fields[2].strip() != '*'
    dow_restricted = fields[4].strip() != '*'

    def day_matches(dt):
        dom_ok = dt.day in doms
        dow_ok = (dt.weekday() + 1) % 7 in dows  # convert Mon=0 -> Sun=0
        if dom_restricted and dow_restricted:
            return dom_ok or dow_ok
        return dom_ok and dow_ok

    start = after.replace(second=0, microsecond=0) + datetime.timedelta(minutes=1)
    limit = start + datetime.timedelta(days=366 * 5 + 2)

    minute_list = sorted(minutes)
    hour_list = sorted(hours)

    dt = start
    while dt < limit:
        if dt.month not in months:
            # jump to first day of next month
            if dt.month == 12:
                dt = dt.replace(year=dt.year + 1, month=1, day=1, hour=0, minute=0)
            else:
                dt = dt.replace(month=dt.month + 1, day=1, hour=0, minute=0)
            continue
        if not day_matches(dt):
            dt = (dt + datetime.timedelta(days=1)).replace(hour=0, minute=0)
            continue
        if dt.hour not in hours:
            nxt = None
            for h in hour_list:
                if h > dt.hour:
                    nxt = h
                    break
            if nxt is None:
                dt = (dt + datetime.timedelta(days=1)).replace(hour=0, minute=0)
            else:
                dt = dt.replace(hour=nxt, minute=0)
            continue
        if dt.minute not in minutes:
            nxt = None
            for m in minute_list:
                if m > dt.minute:
                    nxt = m
                    break
            if nxt is None:
                dt = (dt + datetime.timedelta(hours=1)).replace(minute=0)
            else:
                dt = dt.replace(minute=nxt)
            continue
        return dt

    raise ValueError("no matching time within 5 years")
