import copy


def merge(base: dict, *overrides: dict) -> dict:
    result = copy.deepcopy(base)

    for override in overrides:
        if not isinstance(override, dict):
            raise TypeError("override must be a dict")
        _apply_override(result, override)

    return result


def _apply_override(target: dict, override: dict) -> None:
    for key, value in override.items():
        if key.endswith("+") and len(key) > 1:
            real_key = key[:-1]
            if value is None:
                target.pop(real_key, None)
                continue
            if not isinstance(value, list):
                raise TypeError(
                    f"append key {key!r} requires a list value"
                )
            if real_key in target:
                existing = target[real_key]
                if not isinstance(existing, list):
                    raise TypeError(
                        f"cannot append to non-list base value at {real_key!r}"
                    )
                target[real_key] = existing + copy.deepcopy(value)
            else:
                target[real_key] = copy.deepcopy(value)
            continue

        if value is None:
            target.pop(key, None)
            continue

        if isinstance(value, dict):
            existing = target.get(key)
            if isinstance(existing, dict):
                _apply_override(existing, value)
            else:
                target[key] = {}
                _apply_override(target[key], value)
        else:
            target[key] = copy.deepcopy(value)
