import re

_UNITS = [('d', 86400), ('h', 3600), ('m', 60), ('s', 1)]
_ORDER = {u: i for i, (u, _) in enumerate(_UNITS)}

_PART_RE = re.compile(r'^(\d+)([dhms])$', re.IGNORECASE)


def parse_duration(s: str) -> int:
    if not isinstance(s, str) or s == '':
        raise ValueError('empty duration')
    if any(ch not in '0123456789dhmsDHMS ' for ch in s):
        raise ValueError('invalid character')
    parts = s.split(' ')
    if '' in parts:
        raise ValueError('invalid spacing')
    total = 0
    seen = set()
    last_order = -1
    for part in parts:
        m = _PART_RE.match(part)
        if not m:
            raise ValueError('invalid part')
        num, unit = m.group(1), m.group(2).lower()
        idx = _ORDER[unit]
        if unit in seen:
            raise ValueError('repeated unit')
        if idx <= last_order:
            raise ValueError('wrong order')
        seen.add(unit)
        last_order = idx
        total += int(num) * _UNITS[idx][1]
    return total


def format_duration(seconds: int) -> str:
    if not isinstance(seconds, int) or isinstance(seconds, bool):
        raise ValueError('invalid input')
    if seconds < 0:
        raise ValueError('negative duration')
    if seconds == 0:
        return '0s'
    out = []
    rem = seconds
    for unit, size in _UNITS:
        if rem >= size:
            count, rem = divmod(rem, size)
            out.append(f'{count}{unit}')
    return ''.join(out)
