def flatten(obj, sep="."):
    if not isinstance(obj, dict):
        raise TypeError("top-level object must be a dict")

    result = {}

    def check_key(k):
        if not isinstance(k, str):
            raise ValueError("keys must be strings")
        if sep in k:
            raise ValueError("keys must not contain the separator")

    def walk(node, prefix):
        if isinstance(node, dict):
            if not node:
                result[prefix] = {}
                return
            for k, v in node.items():
                check_key(k)
                new_prefix = prefix + sep + k if prefix else k
                walk(v, new_prefix)
        elif isinstance(node, list):
            if not node:
                result[prefix] = []
                return
            for i, v in enumerate(node):
                new_prefix = prefix + sep + str(i) if prefix else str(i)
                walk(v, new_prefix)
        else:
            result[prefix] = node

    walk(obj, "")
    return result


def _parse_segment(seg):
    """Return int if seg is a canonical non-negative integer, else None."""
    if seg and seg.isdigit() and (seg == "0" or seg[0] != "0"):
        return int(seg)
    return None


def unflatten(flat, sep="."):
    if not isinstance(flat, dict):
        raise TypeError("input must be a dict")

    # Build a tree of path segments -> leaf value using a trie.
    root = {}
    LEAF = object()

    for key, value in flat.items():
        if not isinstance(key, str):
            raise ValueError("keys must be strings")
        segments = key.split(sep) if key != "" else [""]
        # Reject empty segments (e.g. leading/trailing sep or double sep)
        for seg in segments:
            if seg == "":
                raise ValueError("invalid path: empty segment")
        node = root
        for seg in segments:
            if seg in node and node[seg] is LEAF:
                raise ValueError("conflict at path segment %r" % seg)
            if seg not in node:
                node[seg] = {}
            node = node[seg]
        if node is not LEAF and node:
            raise ValueError("conflict at path %r" % key)
        if node is LEAF:
            raise ValueError("duplicate path %r" % key)
        # node is a dict; mark as leaf
        node.clear()
        node[LEAF] = value

    def build(node):
        if LEAF in node:
            return node[LEAF]
        # Determine whether all keys are list indices
        keys = list(node.keys())
        indices = [_parse_segment(k) for k in keys]
        if all(i is not None for i in indices):
            # Must be dense 0..n-1
            idx_set = set(indices)
            n = len(indices)
            if idx_set != set(range(n)):
                raise ValueError("list indices must be dense")
            lst = [None] * n
            for k in keys:
                lst[_parse_segment(k)] = build(node[k])
            return lst
        else:
            result = {}
            for k in keys:
                result[k] = build(node[k])
            return result

    return build(root)
