    return None


def unflatten(flat, sep="."):
    if not isinstance(flat, dict):
        raise TypeError("input must be a dict")

    LEAF = object()

    # Build a trie of path segments -> leaf value.
    root = {}

    for key, value in flat.items():
        if not isinstance(key, str):
            raise ValueError("keys must be strings")
        segments = key.split(sep) if key != "" else [""]
        for seg in segments:
            if seg == "":
                raise ValueError("invalid path: empty segment")
        node = root
        for seg in segments:
            if seg in node:
                child = node[seg]
                if child is LEAF:
                    raise ValueError("conflict at path segment %r" % seg)
                node = child
            else:
                node[seg] = {}
                node = node[seg]
        if node is LEAF:
            raise ValueError("duplicate path %r" % key)
        if node:
            # There are already children under this path: conflict.
            raise ValueError("conflict at path %r" % key)
        node[LEAF] = value

    def build(node):
        if LEAF in node:
            return node[LEAF]
        keys = list(node.keys())
        indices = [_parse_segment(k) for k in keys]
        if all(i is not None for i in indices):
            n = len(indices)
            if set(indices) != set(range(n)):
                raise ValueError("list indices must be dense")
            lst = [None] * n
            for k in keys:
                lst[_parse_segment(k)] = build(node[k])
            return lst
        else:
            result = {}
            for k in keys:
                result[k] = build(node[k])
            return result

    return build(root)
