import re

TOKEN_RE = re.compile(r"""
    \s+
  | (?P<num>(?:\d+\.\d*|\.\d+|\d+))
  | (?P<id>[A-Za-z_][A-Za-z0-9_]*)
  | (?P<op>\|\||&&|==|!=|<=|>=|[-+*/%^!?:()<>,])
""", re.VERBOSE)


def tokenize(expr):
    tokens = []
    pos = 0
    n = len(expr)
    while pos < n:
        m = TOKEN_RE.match(expr, pos)
        if not m:
            raise SyntaxError("bad token at %d" % pos)
        pos = m.end()
        if m.lastgroup is None:
            continue
        tokens.append((m.lastgroup, m.group(m.lastgroup)))
    return tokens


class Parser:
    def __init__(self, tokens, env):
        self.tokens = tokens
        self.pos = 0
        self.env = env if env is not None else {}

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return (None, None)

    def advance(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def expect(self, value):
        kind, val = self.peek()
        if val != value or kind != "op":
            raise SyntaxError("expected %r" % value)
        self.advance()

    def parse(self):
        if not self.tokens:
            raise SyntaxError("empty input")
        node = self.parse_conditional()
        if self.pos != len(self.tokens):
            raise SyntaxError("trailing tokens")
        return node

    # 1. conditional
    def parse_conditional(self):
        cond = self.parse_or()
        if self.peek() == ("op", "?"):
            self.advance()
            then = self.parse_conditional()
            self.expect(":")
            els = self.parse_conditional()
            return ("cond", cond, then, els)
        return cond

    # 2. ||
    def parse_or(self):
        node = self.parse_and()
        while self.peek() == ("op", "||"):
            self.advance()
            node = ("or", node, self.parse_and())
        return node

    def parse_and(self):
        node = self.parse_cmp()
        while self.peek() == ("op", "&&"):
            self.advance()
            node = ("and", node, self.parse_cmp())
        return node

    # 3. comparisons (non-associative)
    def parse_cmp(self):
        node = self.parse_add()
        kind, val = self.peek()
        if kind == "op" and val in ("==", "!=", "<", "<=", ">", ">="):
            self.advance()
            rhs = self.parse_add()
            node = ("cmp", val, node, rhs)
            kind2, val2 = self.peek()
            if kind2 == "op" and val2 in ("==", "!=", "<", "<=", ">", ">="):
                raise SyntaxError("chained comparison")
        return node

    # 4. + -
    def parse_add(self):
        node = self.parse_mul()
        while True:
            kind, val = self.peek()
            if kind == "op" and val in ("+", "-"):
                self.advance()
                node = ("bin", val, node, self.parse_mul())
            else:
                break
        return node

    # 5. * / %
    def parse_mul(self):
        node = self.parse_unary()
        while True:
            kind, val = self.peek()
            if kind == "op" and val in ("*", "/", "%"):
                self.advance()
                node = ("bin", val, node, self.parse_unary())
            else:
                break
        return node

    # 6. unary
    def parse_unary(self):
        kind, val = self.peek()
        if kind == "op" and val in ("-", "+", "!"):
            self.advance()
            operand = self.parse_unary()
            return ("unary", val, operand)
        return self.parse_power()

    # 7. power, right-associative
    def parse_power(self):
        base = self.parse_atom()
        if self.peek() == ("op", "^"):
            self.advance()
            exponent = self.parse_unary_for_power()
            return ("bin", "^", base, exponent)
        return base

    def parse_unary_for_power(self):
        # right side of ^ : allow unary minus and chained ^
        kind, val = self.peek()
        if kind == "op" and val in ("-", "+", "!"):
            self.advance()
            return ("unary", val, self.parse_unary_for_power())
        base = self.parse_atom()
        if self.peek() == ("op", "^"):
            self.advance()
            exponent = self.parse_unary_for_power()
            return ("bin", "^", base, exponent)
        return base

    # 8. atoms
    def parse_atom(self):
        kind, val = self.peek()
        if kind == "num":
            self.advance()
            if "." in val:
                return ("lit", float(val))
            return ("lit", int(val))
        if kind == "id":
            self.advance()
            if self.peek() == ("op", "("):
                self.advance()
                args = [self.parse_conditional()]
                while self.peek() == ("op", ","):
                    self.advance()
                    args.append(self.parse_conditional())
                self.expect(")")
                return ("call", val, args)
            return ("var", val)
        if kind == "op" and val == "(":
            self.advance()
            node = self.parse_conditional()
            self.expect(")")
            return node
        raise SyntaxError("unexpected token %r" % (val,))


def evaluate_node(node, env):
    t = node[0]
    if t == "lit":
        return node[1]
    if t == "var":
        name = node[1]
        if name not in env:
            raise NameError("unknown variable %r" % name)
        return env[name]
    if t == "cond":
        c = evaluate_node(node[1], env)
        if c != 0:
            return evaluate_node(node[2], env)
        return evaluate_node(node[3], env)
    if t == "or":
        a = evaluate_node(node[1], env)
        if a != 0:
            return 1
        b = evaluate_node(node[2], env)
        return 1 if b != 0 else 0
    if t == "and":
        a = evaluate_node(node[1], env)
        if a == 0:
            return 0
        b = evaluate_node(node[2], env)
        return 1 if b != 0 else 0
    if t == "cmp":
        op = node[1]
        a = evaluate_node(node[2], env)
        b = evaluate_node(node[3], env)
        if op == "==":
            r = a == b
        elif op == "!=":
            r = a != b
        elif op == "<":
            r = a < b
        elif op == "<=":
            r = a <= b
        elif op == ">":
            r = a > b
        else:
            r = a >= b
        return 1 if r else 0
    if t == "unary":
        op = node[1]
        v = evaluate_node(node[2], env)
        if op == "-":
            return -v
        if op == "+":
            return v
        return 1 if v == 0 else 0
    if t == "bin":
        op = node[1]
        a = evaluate_node(node[2], env)
        b = evaluate_node(node[3], env)
        if op == "+":
            return a + b
        if op == "-":
            return a - b
        if op == "*":
            return a * b
        if op == "/":
            if b == 0:
                raise ZeroDivisionError("division by zero")
            if isinstance(a, int) and isinstance(b, int):
                q = a // b
                if q * b == a:
                    return q
                return a / b
            return a / b
        if op == "%":
            if b == 0:
                raise ZeroDivisionError("modulo by zero")
            return a % b
        if op == "^":
            return a ** b
        raise SyntaxError("bad operator %r" % op)
    if t == "call":
        name = node[1]
        if name == "min":
            args = [evaluate_node(a, env) for a in node[2]]
            return min(args)
        if name == "max":
            args = [evaluate_node(a, env) for a in node[2]]
            return max(args)
        if name == "abs":
            if len(node[2]) != 1:
                raise SyntaxError("abs takes exactly one argument")
            return abs(evaluate_node(node[2][0], env))
        raise NameError("unknown function %r" % name)
    raise SyntaxError("bad node")


def evaluate(expr, env=None):
    tokens = tokenize(expr)
    parser = Parser(tokens, env)
    node = parser.parse()
    return evaluate_node(node, env if env is not None else {})
