from collections import deque
import heapq


def route(grid: list[str]) -> tuple[int, str] | None:
    # ---------- validation ----------
    if not isinstance(grid, list) or not grid:
        raise ValueError("grid must be a non-empty list of strings")

    for row in grid:
        if not isinstance(row, str):
            raise ValueError("grid rows must be strings")

    rows = len(grid)
    cols = len(grid[0])

    if cols == 0:
        raise ValueError("grid rows must be non-empty")

    for row in grid:
        if len(row) != cols:
            raise ValueError("ragged grid")

    start = None
    end = None
    pad_positions: dict[str, list[tuple[int, int]]] = {}

    for r in range(rows):
        for c in range(cols):
            ch = grid[r][c]
            if ch == 'S':
                if start is not None:
                    raise ValueError("more than one start")
                start = (r, c)
            elif ch == 'E':
                if end is not None:
                    raise ValueError("more than one end")
                end = (r, c)
            elif ch == '#' or ch == '.':
                pass
            elif '1' <= ch <= '9':
                pass
            elif 'a' <= ch <= 'z':
                pad_positions.setdefault(ch, []).append((r, c))
            else:
                raise ValueError(f"unknown character {ch!r}")

    if start is None:
        raise ValueError("missing start")
    if end is None:
        raise ValueError("missing end")

    for letter, positions in pad_positions.items():
        if len(positions) != 2:
            raise ValueError(f"pad {letter!r} appears {len(positions)} times")

    # ---------- cost lookup ----------
    def cell_cost(r: int, c: int) -> int:
        ch = grid[r][c]
        if ch == '#' or ch == 'S' or ch == 'E' or ch == '.' or ('a' <= ch <= 'z'):
            return 1
        # digit
        return ord(ch) - ord('0')

    # teleport map: position -> partner position
    teleport = {}
    for letter, (p1, p2) in pad_positions.items():
        teleport[p1] = p2
        teleport[p2] = p1

    # ---------- lexicographic order ----------
    # order: D < L < R < T < U
    move_order = ['D', 'L', 'R', 'T', 'U']
    move_rank = {m: i for i, m in enumerate(move_order)}

    deltas = {
        'U': (-1, 0),
        'D': (1, 0),
        'L': (0, -1),
        'R': (0, 1),
    }

    # ---------- Dijkstra with lexicographic tie-breaking ----------
    #
    # We compute, for every reachable cell, the best (cost, moves) pair.
    # A pair (cost1, moves1) is better than (cost2, moves2) if
    # cost1 < cost2, or cost1 == cost2 and moves1 < moves2 lexicographically.
    #
    # Since edge costs are positive but not all equal, we use Dijkstra.
    # The "distance" is a tuple (cost, moves_string).  Comparing moves strings
    # for every relaxation is fine because strings are short and we only do
    # it when costs are equal.  To keep it efficient we store the best
    # moves string per cell.

    INF = float('inf')
    best_cost = [[INF] * cols for _ in range(rows)]
    best_moves = [[''] * cols for _ in range(rows)]

    sr, sc = start
    best_cost[sr][sc] = 0
    best_moves[sr][sc] = ''

    # heap entries: (cost, moves_string, r, c)
    heap = [(0, '', sr, sc)]

    while heap:
        cost, moves, r, c = heapq.heappop(heap)

        if cost != best_cost[r][c] or moves != best_moves[r][c]:
            continue

        if (r, c) == end:
            # Dijkstra with positive weights: first time we pop the end
            # with the best (cost, moves) tuple is final.
            break

        # generate neighbours in lexicographic order of move letters
        # so that among equal-cost paths the smallest prefix is considered
        # first.  (Heap ordering already handles the rest, but generating
        # in order makes ties deterministic.)
        for mv in move_order:
            if mv == 'T':
                if (r, c) not in teleport:
                    continue
                nr, nc = teleport[(r, c)]
                ncost = cost + 2
            else:
                dr, dc = deltas[mv]
                nr = r + dr
                nc = c + dc
                if nr < 0 or nr >= rows or nc < 0 or nc >= cols:
                    continue
                ch = grid[nr][nc]
                if ch == '#':
                    continue
                ncost = cost + cell_cost(nr, nc)

            nmoves = moves + mv

            if ncost < best_cost[nr][nc] or (
                ncost == best_cost[nr][nc] and nmoves < best_moves[nr][nc]
            ):
                best_cost[nr][nc] = ncost
                best_moves[nr][nc] = nmoves
                heapq.heappush(heap, (ncost, nmoves, nr, nc))

    er, ec = end
    if best_cost[er][ec] == INF:
        return None
    return (best_cost[er][ec], best_moves[er][ec])
