import re
from functools import total_ordering


_SEMVER_RE = re.compile(
    r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)'
    r'(?:-((?:[0-9A-Za-z-]+)(?:\.(?:[0-9A-Za-z-]+))*))?'
    r'(?:\+((?:[0-9A-Za-z-]+)(?:\.(?:[0-9A-Za-z-]+))*))?$'
)

_PARTIAL_RE = re.compile(
    r'^v?(0|[1-9]\d*|[xX*])'
    r'(?:\.(0|[1-9]\d*|[xX*]))?'
    r'(?:\.(0|[1-9]\d*|[xX*]))?'
    r'(?:-((?:[0-9A-Za-z-]+)(?:\.(?:[0-9A-Za-z-]+))*))?'
    r'(?:\+((?:[0-9A-Za-z-]+)(?:\.(?:[0-9A-Za-z-]+))*))?$'
)


def _check_prerelease(pre):
    if pre is None:
        return None
    parts = pre.split('.')
    for p in parts:
        if not p:
            raise ValueError('empty identifier')
        if not re.match(r'^[0-9A-Za-z-]+$', p):
            raise ValueError('invalid identifier')
        if p.isdigit() and len(p) > 1 and p[0] == '0':
            raise ValueError('leading zero in numeric prerelease identifier')
    return parts


def _check_build(build):
    if build is None:
        return None
    parts = build.split('.')
    for p in parts:
        if not p or not re.match(r'^[0-9A-Za-z-]+$', p):
            raise ValueError('invalid build identifier')
    return parts


@total_ordering
class Version:
    __slots__ = ('major', 'minor', 'patch', 'prerelease', 'build')

    def __init__(self, major, minor, patch, prerelease=None, build=None):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease
        self.build = build

    def _cmp_key(self):
        return (self.major, self.minor, self.patch)

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare(other) == 0

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare(other) < 0

    def _compare(self, other):
        if self._cmp_key() != other._cmp_key():
            return -1 if self._cmp_key() < other._cmp_key() else 1
        a = self.prerelease
        b = other.prerelease
        if a is None and b is None:
            return 0
        if a is None:
            return 1
        if b is None:
            return -1
        for x, y in zip(a, b):
            xd = x.isdigit()
            yd = y.isdigit()
            if xd and yd:
                xi, yi = int(x), int(y)
                if xi != yi:
                    return -1 if xi < yi else 1
            elif xd:
                return -1
            elif yd:
                return 1
            else:
                if x != y:
                    return -1 if x < y else 1
        if len(a) != len(b):
            return -1 if len(a) < len(b) else 1
        return 0

    def __hash__(self):
        return hash((self.major, self.minor, self.patch, tuple(self.prerelease) if self.prerelease else None))

    def __repr__(self):
        s = '%d.%d.%d' % (self.major, self.minor, self.patch)
        if self.prerelease:
            s += '-' + '.'.join(self.prerelease)
        if self.build:
            s += '+' + '.'.join(self.build)
        return 'Version(%s)' % s


def parse(v):
    if not isinstance(v, str):
        raise ValueError('not a string')
    s = v
    if s.startswith('v') or s.startswith('='):
        s = s[1:]
    m = _SEMVER_RE.match(s)
    if not m:
        raise ValueError('invalid version: %r' % v)
    major = int(m.group(1))
    minor = int(m.group(2))
    patch = int(m.group(3))
    pre = _check_prerelease(m.group(4))
    build = _check_build(m.group(5))
    return Version(major, minor, patch, pre, build)


class _Comparator:
    __slots__ = ('op', 'ver')

    def __init__(self, op, ver):
        self.op = op
        self.ver = ver

    def matches(self, v):
        c = v._compare(self.ver)
        op = self.op
        if op == '<':
            return c < 0
        if op == '<=':
            return c <= 0
        if op == '>':
            return c > 0
        if op == '>=':
            return c >= 0
        return c == 0

    def has_prerelease_for(self, v):
        return (self.ver.prerelease is not None
                and self.ver.major == v.major
                and self.ver.minor == v.minor
                and self.ver.patch == v.patch)


def _parse_partial(s):
    m = _PARTIAL_RE.match(s)
    if not m:
        raise ValueError('invalid partial version: %r' % s)
    groups = [m.group(1), m.group(2), m.group(3)]
    nums = []
    wild = False
    for g in groups:
        if g is None:
            nums.append(None)
            continue
        if wild:
            nums.append(None)
            continue
        if g in ('x', 'X', '*'):
            wild = True
            nums.append(None)
            continue
        nums.append(int(g))
    pre = _check_prerelease(m.group(4))
    build = _check_build(m.group(5))
    # If any earlier component is wild, later must be absent (we've set None)
    # If prerelease present, all three components must be present
    if pre is not None:
        if nums[0] is None or nums[1] is None or nums[2] is None:
            raise ValueError('prerelease requires full version')
    return nums, pre, build


def _zero_ver(major, minor, patch):
    return Version(major, minor, patch)


def _expand_comparator(op, partial_str):
    nums, pre, build = _parse_partial(partial_str)
    major, minor, patch = nums
    if major is None:
        # wildcard everything: matches all
        if op in ('=', '', None):
            return []
        if op == '<':
            return None  # matches nothing
        if op == '<=':
            return None
        if op == '>':
            return None
        if op == '>=':
            return []
        return []
    if minor is None:
        # major only
        if op in ('=', '', None):
            return [_Comparator('>=', _zero_ver(major, 0, 0)),
                    _Comparator('<', _zero_ver(major + 1, 0, 0))]
        if op == '>':
            return [_Comparator('>=', _zero_ver(major + 1, 0, 0))]
        if op == '>=':
            return [_Comparator('>=', _zero_ver(major, 0, 0))]
        if op == '<':
            return [_Comparator('<', _zero_ver(major, 0, 0))]
        if op == '<=':
            return [_Comparator('<', _zero_ver(major + 1, 0, 0))]
    if patch is None:
        if op in ('=', '', None):
            return [_Comparator('>=', _zero_ver(major, minor, 0)),
                    _Comparator('<', _zero_ver(major, minor + 1, 0))]
        if op == '>':
            return [_Comparator('>=', _zero_ver(major, minor + 1, 0))]
        if op == '>=':
            return [_Comparator('>=', _zero_ver(major, minor, 0))]
        if op == '<':
            return [_Comparator('<', _zero_ver(major, minor, 0))]
        if op == '<=':
            return [_Comparator('<', _zero_ver(major, minor + 1, 0))]
    # full version
    ver = Version(major, minor, patch, pre, build)
    if op in ('=', '', None):
        return [_Comparator('=', ver)]
    return [_Comparator(op, ver)]


def _expand_tilde(s):
    nums, pre, build = _parse_partial(s)
    major, minor, patch = nums
    if major is None:
        return []
    if minor is None:
        return [_Comparator('>=', _zero_ver(major, 0, 0)),
                _Comparator('<', _zero_ver(major + 1, 0, 0))]
    if patch is None:
        return [_Comparator('>=', _zero_ver(major, minor, 0)),
                _Comparator('<', _zero_ver(major, minor + 1, 0))]
    ver = Version(major, minor, patch, pre, build)
    return [_Comparator('>=', ver),
            _Comparator('<', _zero_ver(major, minor + 1, 0))]


def _expand_caret(s):
    nums, pre, build = _parse_partial(s)
    major, minor, patch = nums
    if major is None:
        return []
    if minor is None:
        return [_Comparator('>=', _zero_ver(major, 0, 0)),
                _Comparator('<', _zero_ver(major + 1, 0, 0))]
    if patch is None:
        if major == 0:
            return [_Comparator('>=', _zero_ver(0, minor, 0)),
                    _Comparator('<', _zero_ver(0, minor + 1, 0))]
        return [_Comparator('>=', _zero_ver(major, minor, 0)),
                _Comparator('<', _zero_ver(major + 1, 0, 0))]
    ver = Version(major, minor, patch, pre, build)
    if major > 0:
        upper = _zero_ver(major + 1, 0, 0)
    elif minor > 0:
        upper = _zero_ver(0, minor + 1, 0)
    else:
        upper = _zero_ver(0, 0, patch + 1)
    return [_Comparator('>=', ver), _Comparator('<', upper)]


def _expand_hyphen(lower_s, upper_s):
    lnums, lpre, lbuild = _parse_partial(lower_s)
    unums, upre, ubuild = _parse_partial(upper_s)
