        # We'll require each segment between hyphens to have exactly one token on each side
        if len(segments) != 2:
            raise ValueError('invalid hyphen range')
        lower_seg = segments[0]
        upper_seg = segments[1]
        if len(lower_seg) != 1 or len(upper_seg) != 1:
            raise ValueError('invalid hyphen range')
        return _expand_hyphen(lower_seg[0], upper_seg[0])
    result = []
    for t in tokens:
        m = _COMPARATOR_TOKEN_RE.match(t)
        op = m.group(1)
        rest = m.group(2)
        if rest == '' and op is None:
            raise ValueError('invalid comparator: %r' % t)
        if op == '~':
            result.extend(_expand_tilde(rest))
        elif op == '^':
            result.extend(_expand_caret(rest))
        else:
            res = _expand_comparator(op, rest)
            if res is None:
                # matches nothing
                result.append(_Comparator('<', _zero_ver(0, 0, 0)))
                result.append(_Comparator('>', _zero_ver(0, 0, 0)))
            else:
                result.extend(res)
    return result


def _parse_range(rng):
    if not isinstance(rng, str):
        raise ValueError('range must be string')
    sets = rng.split('||')
    parsed_sets = []
    for s in sets:
        parsed_sets.append(_parse_set(s))
    return parsed_sets


def _satisfies_set(v, comparators):
    if v.prerelease is not None:
        allowed = False
        for c in comparators:
            if c.has_prerelease_for(v):
                allowed = True
                break
        if not allowed:
            return False
    for c in comparators:
        if not c.matches(v):
            return False
    return True


def satisfies(version, rng):
    v = parse(version)
    sets = _parse_range(rng)
    for comps in sets:
        if _satisfies_set(v, comps):
            return True
    return False


def max_satisfying(versions, rng):
    best = None
    best_ver = None
    for s in versions:
        try:
            v = parse(s)
        except ValueError:
            continue
        if not satisfies(s, rng):
            continue
        if best_ver is None or v > best_ver:
            best_ver = v
            best = s
    return best
