def split_command(line: str, env: dict[str, str]) -> list[str]:
    # We build words as lists of "segments", each segment is (text, split_flag)
    # split_flag True means this segment came from an unquoted expansion and may be split.
    words = []  # list of lists of (text, split)
    cur = None  # current word being built: list of segments, or None if not started

    i = 0
    n = len(line)

    def ensure_word():
        nonlocal cur
        if cur is None:
            cur = []
        return cur

    def finish_word():
        nonlocal cur
        if cur is None:
            return
        # Perform field splitting across segments.
        # We join segments but must respect split boundaries.
        # Approach: build a list of resulting words by processing segments.
        # A non-split segment is appended literally. A split segment is broken
        # on whitespace into pieces; whitespace at boundaries separates words.
        result_words = []
        current = ""
        # Track whether current word has any content (to distinguish empty from non-existent)
        has_content = False
        # Also track whether current came from a quoted empty part
        # We'll handle by using a flag: we always start a word when segment begins.
        # Simpler: process char by char with a "pending word" concept.

        # We'll rebuild using a token list where each char is (char, splittable)
        # Actually let's just iterate segments.
        pieces = []  # list of (char, splittable) or just strings
        for text, split in cur:
            if split:
                pieces.append(("S", text))
            else:
                pieces.append(("L", text))

        # Now build words: a word is a sequence; when we hit splittable whitespace
        # and current word is non-empty (has content), we end it.
        # But empty quoted strings must produce empty word. So track "started".
        out_words = []
        buf = []
        started = False

        def flush():
            nonlocal buf, started
            if started:
                out_words.append("".join(buf))
                buf = []
                started = False

        for kind, text in pieces:
            if kind == "L":
                buf.append(text)
                started = True
            else:
                # splittable: split on spaces, tabs, newlines
                j = 0
                L = len(text)
                while j < L:
                    ch = text[j]
                    if ch in " \t\n":
                        # whitespace: ends current word if started
                        flush()
                        j += 1
                    else:
                        # accumulate run of non-whitespace
                        k = j
                        while k < L and text[k] not in " \t\n":
                            k += 1
                        buf.append(text[j:k])
                        started = True
                        j = k
        flush()

        words.extend(out_words)
        cur = None

    while i < n:
        ch = line[i]
        if ch in " \t\n":
            finish_word()
            i += 1
            continue
        if ch == "'":
            # single quoted
            j = line.find("'", i + 1)
            if j == -1:
                raise ValueError("unterminated single quote")
            ensure_word().append((line[i + 1:j], False))
            i = j + 1
            continue
        if ch == '"':
            # double quoted
            i += 1
            seg = []
            while True:
                if i >= n:
                    raise ValueError("unterminated double quote")
                c = line[i]
                if c == '"':
                    i += 1
                    break
                if c == '\\':
                    if i + 1 >= n:
                        raise ValueError("trailing backslash")
                    nxt = line[i + 1]
                    if nxt == '\n':
                        i += 2
                        continue
                    if nxt in '$"\\':
                        seg.append(nxt)
                        i += 2
                        continue
                    else:
                        seg.append('\\')
                        i += 1
                        continue
                if c == '$':
                    text, i = expand(line, i, env)
                    seg.append(text)
                    continue
                seg.append(c)
                i += 1
            ensure_word().append(("".join(seg), False))
            continue
        if ch == '\\':
            if i + 1 >= n:
                raise ValueError("trailing backslash")
            nxt = line[i + 1]
            if nxt == '\n':
                i += 2
                continue
            ensure_word().append((nxt, False))
            i += 2
            continue
        if ch == '$':
            text, i = expand(line, i, env)
            ensure_word().append((text, True))
            continue
        # ordinary char
        ensure_word().append((ch, False))
        i += 1

    finish_word()
    return words


def expand(line: str, i: int, env: dict) -> tuple[str, int]:
    """line[i] == '$'. Returns (expanded_text, new_index)."""
    n = len(line)
    j = i + 1
    if j >= n:
        return ("$", i + 1)
    c = line[j]
    if c == '{':
        # find matching }
        k = j + 1
        depth = 1
        # We need to handle ${NAME}, ${NAME:-default}, ${NAME-default}
        # Find closing } - no nested braces supported? Spec doesn't mention nesting.
        # But default text may contain ${...}. Let's handle nested ${ } by tracking.
        while k < n:
            if line[k] == '{' and k > 0 and line[k-1] == '$':
                depth += 1
            elif line[k] == '}':
                depth -= 1
                if depth == 0:
                    break
            k += 1
        if k >= n:
            raise ValueError("unterminated ${")
        inner = line[j + 1:k]
        # parse NAME, NAME:-default, NAME-default
        # find first ':' or '-'
        # NAME is [A-Za-z_][A-Za-z0-9_]*
        m = 0
        L = len(inner)
        while m < L and (inner[m].isalnum() or inner[m] == '_'):
            m += 1
        name = inner[:m]
        if m == 0 or not (name[0].isalpha() or name[0] == '_'):
            raise ValueError("bad substitution")
        rest = inner[m:]
        if rest == "":
            value = env.get(name, "")
        elif rest.startswith(":-"):
            default_text = rest[2:]
            val = env.get(name, "")
            if val == "":
                value = expand_string(default_text, env)
            else:
                value = val
        elif rest.startswith("-"):
            default_text = rest[1:]
            if name in env:
                value = env[name]
            else:
                value = expand_string(default_text, env)
        else:
            raise ValueError("bad substitution")
        return (value, k + 1)
    if c.isalpha() or c == '_':
        k = j
        while k < n and (line[k].isalnum() or line[k] == '_'):
            k += 1
        name = line[j:k]
        return (env.get(name, ""), k)
    return ("$", i + 1)


def expand_string(s: str, env: dict) -> str:
    """Expand $ constructs in a string (used for defaults). No quote processing."""
    out = []
    i = 0
    n = len(s)
    while i < n:
        if s[i] == '$':
            text, i = expand(s, i, env)
            out.append(text)
        else:
            out.append(s[i])
            i += 1
    return "".join(out)
