from __future__ import annotations

import types
import typing
from dataclasses import dataclass, fields, MISSING
from typing import Any, Literal, Union, get_args, get_origin, get_type_hints


class LoadError(ValueError):
    def __init__(self, path: str, message: str):
        self.path = path
        self.message = message
        super().__init__(f"{path}: {message}")

    def __str__(self) -> str:
        return f"{self.path}: {self.message}"


def _join_field(path: str, name: str) -> str:
    return f"{path}.{name}"


def _join_index(path: str, index: int) -> str:
    return f"{path}[{index}]"


def _is_dataclass_type(tp: Any) -> bool:
    return isinstance(tp, type) and hasattr(tp, "__dataclass_fields__")


def _type_name(tp: Any) -> str:
    return getattr(tp, "__name__", repr(tp))


def _load_value(tp: Any, data: Any, path: str) -> Any:
    origin = get_origin(tp)

    # Union / Optional
    if origin is Union or origin is types.UnionType:
        args = get_args(tp)
        # Special-case Optional[T] (T | None): non-null data -> report inner error
        non_none = [a for a in args if a is not type(None)]
        if len(non_none) == 1 and len(args) == 2 and type(None) in args:
            inner = non_none[0]
            if data is None:
                return None
            return _load_value(inner, data, path)
        # General union: try left to right
        last_error: LoadError | None = None
        for arg in args:
            try:
                return _load_value(arg, data, path)
            except LoadError as e:
                last_error = e
        raise LoadError(path, f"value {data!r} does not match any member of {tp!r}")

    # Literal
    if origin is Literal:
        allowed = get_args(tp)
        for lit in allowed:
            if type(lit) is type(data) and lit == data:
                return data
        raise LoadError(path, f"value {data!r} is not one of {allowed!r}")

    # list[T]
    if origin is list:
        args = get_args(tp)
        elem_tp = args[0] if args else Any
        if not isinstance(data, list):
            raise LoadError(path, f"expected list, got {type(data).__name__}")
        return [_load_value(elem_tp, item, _join_index(path, i)) for i, item in enumerate(data)]

    # dict[str, T]
    if origin is dict:
        args = get_args(tp)
        key_tp = args[0] if args else Any
        val_tp = args[1] if len(args) > 1 else Any
        if not isinstance(data, dict):
            raise LoadError(path, f"expected dict, got {type(data).__name__}")
        out = {}
        for k, v in data.items():
            kp = _join_field(path, str(k))
            new_key = _load_value(key_tp, k, kp) if key_tp is not Any else k
            out[new_key] = _load_value(val_tp, v, kp)
        return out

    # tuple[...]
    if origin is tuple:
        args = get_args(tp)
        if not isinstance(data, list):
            raise LoadError(path, f"expected list for tuple, got {type(data).__name__}")
        if len(args) == 2 and args[1] is Ellipsis:
            elem_tp = args[0]
            return tuple(
                _load_value(elem_tp, item, _join_index(path, i))
                for i, item in enumerate(data)
            )
        if len(args) == 0:
            # plain tuple
            return tuple(data)
        if len(data) != len(args):
            raise LoadError(
                path, f"expected tuple of length {len(args)}, got {len(data)}"
            )
        return tuple(
            _load_value(arg, item, _join_index(path, i))
            for i, (arg, item) in enumerate(zip(args, data))
        )

    # None type
    if tp is type(None) or tp is None:
        if data is None:
            return None
        raise LoadError(path, f"expected null, got {type(data).__name__}")

    # scalars
    if tp is bool:
        if isinstance(data, bool):
            return data
        raise LoadError(path, f"expected bool, got {type(data).__name__}")

    if tp is int:
        if isinstance(data, bool) or not isinstance(data, int):
            raise LoadError(path, f"expected int, got {type(data).__name__}")
        return data

    if tp is float:
        if isinstance(data, bool):
            raise LoadError(path, f"expected float, got bool")
        if isinstance(data, float):
            return data
        if isinstance(data, int):
            return float(data)
        raise LoadError(path, f"expected float, got {type(data).__name__}")

    if tp is str:
        if isinstance(data, str):
            return data
        raise LoadError(path, f"expected str, got {type(data).__name__}")

    if tp is Any:
        return data

    # nested dataclass
    if _is_dataclass_type(tp):
        return _load_dataclass(tp, data, path)

    raise LoadError(path, f"unsupported annotation {tp!r}")


def _load_dataclass(cls: type, data: Any, path: str) -> Any:
    if not isinstance(data, dict):
        raise LoadError(path, f"expected object, got {type(data).__name__}")

    hints = get_type_hints(cls)
    field_list = fields(cls)
    field_names = {f.name for f in field_list}

    # Unknown keys check first (input order)
    for k in data.keys():
        if k not in field_names:
            raise LoadError(_join_field(path, str(k)), "unknown key")

    kwargs = {}
    for f in field_list:
        fpath = _join_field(path, f.name)
        if f.name in data:
            value = data[f.name]
        else:
            if f.default is not MISSING:
                kwargs[f.name] = f.default
                continue
            if f.default_factory is not MISSING:
                kwargs[f.name] = f.default_factory()
                continue
            raise LoadError(fpath, "missing required field")
        tp = hints.get(f.name, Any)
        kwargs[f.name] = _load_value(tp, value, fpath)

    return cls(**kwargs)


def load(cls: type, data: Any) -> Any:
    return _load_dataclass(cls, data, "$")
