  echo "usage: solution.sh [-d DELIM] [-s] COLUMN [FILE]" >&2
  exit 2
}

while getopts 'd:s' opt; do
  case "$opt" in
    d) delim="$OPTARG" ;;
    s) summarize=1 ;;
    *) usage ;;
  esac
