    if (val ~ /^[+-]?([0-9]+(\.[0-9]+)?|\.[0-9]+)$/) {
      num = val + 0
      count++
      sum += num
      if (count == 1) { minv = num; maxv = num }
      else { if (num < minv) minv = num; if (num > maxv) maxv = num }
    }
  } else {
    print esc(val)
  }
}

