  i = 1
  field = ""
  inquote = 0
  inField = 0
  rowNf = 0
  headerDone = 0
  targetIdx = 0
  colFound = 0
  count = 0; sum = 0; minv = 0; maxv = 0
  rowTarget = ""
  rowHasTarget = 0

