          inquote = 1
          inField = 1
          i++
        } else {
          field = field c
          i++
        }
      } else if (c == dch) {
        rowNf++
        if (headerDone) {
          if (rowNf == targetIdx) { rowTarget = field; rowHasTarget = 1 }
        } else {
          if (mode == "name" && !colFound && field == colspec) {
            targetIdx = rowNf
            colFound = 1
          }
        }
        field = ""
        inField = 0
        i++
      } else if (c == "\n") {
        rowNf++
        if (headerDone) {
          if (rowNf == targetIdx) { rowTarget = field; rowHasTarget = 1 }
          if (!rowHasTarget && targetIdx > rowNf) { rowTarget = ""; rowHasTarget = 1 }
          if (rowHasTarget) emit(rowTarget)
          rowHasTarget = 0
          rowTarget = ""
        } else {
          if (mode == "name" && !colFound && field == colspec) { targetIdx = rowNf; colFound = 1 }
          headerDone = 1
          if (mode == "index") {
            if (wantIdx >= 1 && wantIdx <= rowNf) { targetIdx = wantIdx; colFound = 1 }
          }
          if (!colFound) {
            print "error: unknown column: " colspec > "/dev/stderr"
            exit 3
          }
        }
        field = ""
        inField = 0
        rowNf = 0
        i++
      } else if (c == "\r" && i < n && substr(buf, i+1, 1) == "\n") {
        i++
      } else {
        field = field c
        inField = 1
        i++
      }
    }
  }

  if (inquote) {
    print "error: unterminated quote at end of input" > "/dev/stderr"
    exit 4
  }

  if (inField || rowNf > 0) {
    rowNf++
    if (!headerDone) {
      if (mode == "name" && !colFound && field == colspec) { targetIdx = rowNf; colFound = 1 }
      headerDone = 1
      if (mode == "index") {
        if (wantIdx >= 1 && wantIdx <= rowNf) { targetIdx = wantIdx; colFound = 1 }
      }
      if (!colFound) {
        print "error: unknown column: " colspec > "/dev/stderr"
        exit 3
      }
    } else {
      if (rowNf == targetIdx) { rowTarget = field; rowHasTarget = 1 }
      if (!rowHasTarget && targetIdx > rowNf) { rowTarget = ""; rowHasTarget = 1 }
      if (rowHasTarget) emit(rowTarget)
    }
  }

  if (!headerDone) {
    print "error: unknown column: " colspec > "/dev/stderr"
    exit 3
  }

  if (summarize) {
    if (count == 0) print "count=0"
    else printf "count=%d sum=%g min=%g max=%g\n", count, sum, minv, maxv
  }
}
